//! The built-in names the front end needs, read from `spec/builtins.txt`
//! (generated by the Go implementation). Resolve needs the prelude names;
//! the module lists describe the `_native.*` bridges.

use std::collections::BTreeMap;
use std::sync::OnceLock;

const SPEC: &str = include_str!("../../../spec/builtins.txt");

// ---- Where the Rust implementation differs from `spec/builtins.txt` ----
//
// The spec is generated by the Go implementation, which keeps atoms
// (stage 3b replaced them with agents in Rust only). These three lists
// are the whole difference, kept here in one place: `builtins()` applies
// them, so resolve, the boot and the spec tests all read the same names.
// Stage 6 (the release switch) folds them into the spec.

/// Prelude natives of the spec that the Rust implementation does not
/// have: Go's atoms. (`swap` and `deref` come back as agent functions.)
const RUST_PRELUDE_NATIVES_REMOVED: &[&str] = &["atom", "deref", "swap"];

/// The public names of `extras/rust/agent.fung`, which only the Rust boot
/// reads (`crate::extras::AGENT`); they join the prelude. The loader test
/// `agent_fung_exports_match_the_list` keeps this list honest.
const RUST_PRELUDE_AGENT: &[&str] = &["agent", "deref", "swap"];

/// Built-in type names (07) of the spec's language that the Rust
/// implementation renames: Go's `atom` is `agent` here. Type names are
/// not in `spec/builtins.txt`; the resolver's list
/// (`resolve/fn_.rs`) is Go's, and `is_builtin_type` applies this.
pub(crate) const RUST_TYPE_RENAMES: &[(&str, &str)] = &[("atom", "agent")];

/// The members the Rust `_native.*` modules add, in the spec's
/// `name(params)` form. Only embedded extras files can import
/// `_native.*` (E0310), so these never change what user code can name.
const RUST_MODULE_MEMBERS: &[(&str, &str)] = &[
    ("_native.conc", "spawn_background(f)"),
    ("_native.conc", "agent_handle(ch)"),
    ("_native.conc", "agent_channel(a)"),
    ("_native.conc", "check_swap(a, f)"),
    ("_native.conc", "agent_ask(a, request, reply)"),
    ("_native.conc", "try_call(f, x)"),
    ("_native.conc", "raise(e)"),
    ("_native.conc", "send_unchecked(ch, v)"),
    ("_native.conc", "agent_busy(ch, on, state=?)"),
    ("_native.conc", "agent_peek(a)"),
];

/// Built-in names by layer. Every list is sorted.
#[derive(Debug, Default)]
pub struct Builtins {
    /// Go values of the prelude (functions and plain values such as `args`).
    pub prelude_native: Vec<String>,
    /// Public names of `extras/prelude.fung`.
    pub prelude_fung: Vec<String>,
    /// Public names of `extras/rust/agent.fung` (Rust only,
    /// `RUST_PRELUDE_AGENT`): also prelude names.
    pub prelude_agent: Vec<String>,
    /// `_native.x` → its member names.
    pub modules: BTreeMap<String, Vec<String>>,
    /// Prelude natives that are functions → their parameter list as the
    /// spec writes it (`xs, sep=?`, `...args`).
    native_params: BTreeMap<String, String>,
    /// `(_native.x, name)` → the member's parameter list.
    module_params: BTreeMap<(String, String), String>,
}

impl Builtins {
    /// The parameter list of a prelude native function as recorded in the
    /// spec, without the parentheses: `xs, f`, `code=?`, `...args`. `None`
    /// for an unknown name or a plain value such as `args`.
    pub fn native_signature(&self, name: &str) -> Option<&str> {
        self.native_params.get(name).map(String::as_str)
    }

    /// The parameter list of a `_native.x` module member as the spec
    /// writes it, like [`Builtins::native_signature`].
    pub fn module_signature(&self, module: &str, name: &str) -> Option<&str> {
        self.module_params
            .get(&(module.to_string(), name.to_string()))
            .map(String::as_str)
    }
}

pub fn builtins() -> &'static Builtins {
    static CELL: OnceLock<Builtins> = OnceLock::new();
    CELL.get_or_init(|| {
        let mut b = parse(SPEC);
        b.apply_rust_differences();
        b
    })
}

impl Builtins {
    /// Every prelude name: the natives, then the public names of
    /// `extras/prelude.fung` and `extras/rust/agent.fung`, sorted.
    pub fn prelude_names(&self) -> Vec<String> {
        let mut names: Vec<String> = self
            .prelude_native
            .iter()
            .chain(&self.prelude_fung)
            .chain(&self.prelude_agent)
            .cloned()
            .collect();
        names.sort();
        names.dedup();
        names
    }

    /// Applies the Rust differences (`RUST_PRELUDE_NATIVES_REMOVED`,
    /// `RUST_PRELUDE_AGENT`, `RUST_MODULE_MEMBERS`), keeping every list
    /// sorted.
    fn apply_rust_differences(&mut self) {
        for name in RUST_PRELUDE_NATIVES_REMOVED {
            assert!(
                self.prelude_native.iter().any(|n| n == name),
                "spec/builtins.txt has no prelude native `{name}` to remove"
            );
            self.prelude_native.retain(|n| n != name);
            self.native_params.remove(*name);
        }
        self.prelude_agent = RUST_PRELUDE_AGENT.iter().map(|n| n.to_string()).collect();
        self.prelude_agent.sort();
        for (module, entry) in RUST_MODULE_MEMBERS {
            let name = entry_name(entry);
            if let Some(params) = entry_params(entry) {
                self.module_params
                    .insert((module.to_string(), name.clone()), params);
            }
            let names = self.modules.entry(module.to_string()).or_default();
            if !names.contains(&name) {
                names.push(name);
                names.sort();
            }
        }
    }
}

/// `name(params)` or a bare `name` → `name`.
fn entry_name(s: &str) -> String {
    s.split('(').next().unwrap_or(s).trim().to_string()
}

/// `name(params)` → `params`; a bare `name` → `None`.
fn entry_params(s: &str) -> Option<String> {
    let (_, rest) = s.split_once('(')?;
    Some(rest.strip_suffix(')').unwrap_or(rest).to_string())
}

fn parse(spec: &str) -> Builtins {
    let mut b = Builtins::default();
    for line in spec.lines() {
        let line = line.trim();
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let mut parts = line.splitn(3, ' ');
        let (kind, layer, rest) = (parts.next(), parts.next(), parts.next());
        match (kind, layer, rest) {
            (Some("prelude"), Some("native"), Some(rest)) => {
                let name = entry_name(rest);
                if let Some(params) = entry_params(rest) {
                    b.native_params.insert(name.clone(), params);
                }
                b.prelude_native.push(name)
            }
            (Some("prelude"), Some("fung"), Some(rest)) => b.prelude_fung.push(entry_name(rest)),
            (Some("module"), Some(module), Some(rest)) => {
                let name = entry_name(rest);
                if let Some(params) = entry_params(rest) {
                    b.module_params
                        .insert((module.to_string(), name.clone()), params);
                }
                b.modules.entry(module.to_string()).or_default().push(name)
            }
            _ => panic!("spec/builtins.txt: malformed line {line:?}"),
        }
    }
    b.prelude_native.sort();
    b.prelude_fung.sort();
    for names in b.modules.values_mut() {
        names.sort();
    }
    b
}

#[cfg(test)]
mod tests {
    use super::builtins;

    #[test]
    fn native_signature_is_the_spec_parameter_list() {
        let b = builtins();
        assert_eq!(b.native_signature("fold"), Some("xs, init, f"));
        assert_eq!(b.native_signature("join"), Some("xs, sep=?"));
        assert_eq!(b.native_signature("print"), Some("...args"));
        assert_eq!(b.native_signature("args"), None);
        assert_eq!(b.native_signature("take"), None);
    }

    /// The Rust differences (stage 3b): Go's atom natives are gone, the
    /// agent functions of `extras/rust/agent.fung` are prelude names.
    #[test]
    fn the_rust_differences_are_applied() {
        let b = builtins();
        for name in ["atom", "swap", "deref"] {
            assert!(!b.prelude_native.iter().any(|n| n == name), "{name}");
            assert_eq!(b.native_signature(name), None, "{name}");
        }
        assert_eq!(b.prelude_agent, ["agent", "deref", "swap"]);
        let names = b.prelude_names();
        assert!(names.windows(2).all(|w| w[0] < w[1]));
        for name in ["agent", "swap", "deref", "print", "take"] {
            assert!(names.iter().any(|n| n == name), "{name}");
        }
        assert!(!names.iter().any(|n| n == "atom"));
    }

    #[test]
    fn module_signature_is_the_spec_parameter_list() {
        let b = builtins();
        assert_eq!(
            b.module_signature("_native.process", "exec"),
            Some("cmd, cwd=?, env=?, stdin=?")
        );
        assert_eq!(b.module_signature("_native.process", "env"), Some("name=?"));
        assert_eq!(
            b.module_signature("_native.conc", "spawn_awaited"),
            Some("f")
        );
        assert_eq!(b.module_signature("_native.fs", "temp_dir"), Some(""));
        // A Rust-only member (`RUST_MODULE_MEMBERS`).
        assert_eq!(
            b.module_signature("_native.conc", "agent_busy"),
            Some("ch, on, state=?")
        );
        assert!(b.modules["_native.conc"].contains(&"try_call".to_string()));
        assert_eq!(b.module_signature("_native.process", "nope"), None);
        assert_eq!(b.module_signature("_native.nope", "exec"), None);
    }
}
